INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'pearl-bay-hotel-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Pearl Bay Hotel in Muharraq.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من فندق خليج اللؤلؤة في Muharraq.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"64-key waterfront boutique hotel blending traditional Muharraq architecture with modern executive hospitality and meeting venues. Focusing on Sea-View Executive Suite (Night), our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"فندق بوتيكي يضم 64 جناحاً على واجهة المحرق يجمع بين العمارة التراثية والضيافة العصرية. من خلال خدمة جناح تنفيذي مطل على البحر (ليلة) نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>64-key waterfront boutique hotel blending traditional Muharraq architecture with modern executive hospitality and meeting venues.</p><p>Focusing on <strong>Sea-View Executive Suite (Night)</strong>, our Muharraq specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>فندق بوتيكي يضم 64 جناحاً على واجهة المحرق يجمع بين العمارة التراثية والضيافة العصرية.</p><p>من خلال خدمة <strong>جناح تنفيذي مطل على البحر (ليلة)</strong>، يعمل فريقنا في Muharraq على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Pearl Bay Hotel', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | فندق خليج اللؤلؤة', 'Executive guide by Pearl Bay Hotel covering Sea-View Executive Suite (Night) benchmarks in Bahrain.', 'دليل تنفيذي من فندق خليج اللؤلؤة حول معايير جناح تنفيذي مطل على البحر (ليلة) في البحرين.', 'Sustainability', '{"hotel","sustainability","Muharraq","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', true, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
